"}, "guard_reviewed_connection()": {"acl": "{postgres=X/postgres,service_role=X/postgres}", "definition": "CREATE OR REPLACE FUNCTION public.guard_reviewed_connection()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare first_id uuid; second_id uuid;
begin
 if TG_TABLE_NAME='connections' then first_id:=NEW.user_1;second_id:=NEW.user_2;
 else
  if TG_OP='UPDATE' and (NEW.status is not distinct from OLD.status or NEW.status<>'accepted') then return NEW; end if;
  first_id:=NEW.sender_id;second_id:=NEW.receiver_id;
 end if;
 if not exists(select 1 from public.profile_reviews where user_id=first_id and status='approved')
 or not exists(select 1 from public.profile_reviews where user_id=second_id and status='approved') then
  raise exception 'Both profiles must be approved before creating a connection';
 end if;
 return NEW;
end $function$
"}, "guard_client_profile_fields()": {"acl": "{postgres=X/postgres,service_role=X/postgres}", "definition": "CREATE OR REPLACE FUNCTION public.guard_client_profile_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if current_user in ('anon', 'authenticated') then
    if TG_TABLE_NAME = 'profiles' then
      if TG_OP = 'UPDATE' and (
        new.id is distinct from old.id or
        new.user_type is distinct from old.user_type
      ) then
        raise exception 'Account identity and role can only be changed through an authorized server workflow.'
          using errcode = '42501';
      end if;
    elsif TG_TABLE_NAME = 'investor_profiles' then
      if TG_OP = 'INSERT' and new.is_verified is true then
        raise exception 'Verification is managed by the server.' using errcode = '42501';
      elsif TG_OP = 'UPDATE' then
        if new.is_verified is distinct from old.is_verified then
          raise exception 'Verification is managed by the server.' using errcode = '42501';
        end if;
        if new.user_id is distinct from old.user_id then
          raise exception 'Profile ownership cannot be changed.' using errcode = '42501';
        end if;
      end if;
      -- Nullable legacy alias must never point at another account.
      new.profile_id := new.user_id;
    elsif TG_TABLE_NAME = 'founder_profiles' then
      if TG_OP = 'UPDATE' and new.user_id is distinct from old.user_id then
        raise exception 'Profile ownership cannot be changed.' using errcode = '42501';
      end if;
    end if;
  end if;
  return new;
end $function$
"}, "passport_evidence_tombstone()": {"acl": "{postgres=X/postgres}", "definition": "CREATE OR REPLACE FUNCTION public.passport_evidence_tombstone()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF NEW.passport_private AND OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL THEN
  UPDATE public.profile_verification_checks c SET passport_state='stale'
   WHERE c.passport_claim AND c.passport_state IN
    ('submitted','in_review','supported','needs_changes','rejected') AND EXISTS
     (SELECT 1 FROM public.profile_verification_evidence l WHERE l.check_id=c.id AND l.evidence_id=NEW.id);
 END IF;
 RETURN NEW;
END $function$
"}, "increment_login_tracking(uuid)": {"acl": "{postgres=X/postgres,=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres}", "definition": "CREATE OR REPLACE FUNCTION public.increment_login_tracking(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  INSERT INTO public.user_auth_tracking (id, last_login, login_count)
  VALUES (p_user_id, now(), 1)
