END;
$function$
"}, "sync_graduation_year()": {"acl": "{postgres=X/postgres,=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres}", "definition": "CREATE OR REPLACE FUNCTION public.sync_graduation_year()
