"}, "guard_reviewed_connection()": {"acl": "{postgres=X/postgres,service_role=X/postgres}", "definition": "CREATE OR REPLACE FUNCTION public.guard_reviewed_connection()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare first_id uuid; second_id uuid;
begin
 if TG_TABLE_NAME='connections' then first_id:=NEW.user_1;second_id:=NEW.user_2;
 else
  if TG_OP='UPDATE' and (NEW.status is not distinct from OLD.status or NEW.status<>'accepted') then return NEW; end if;
  first_id:=NEW.sender_id;second_id:=NEW.receiver_id;
 end if;
 if not exists(select 1 from public.profile_reviews where user_id=first_id and status='approved')
 or not exists(select 1 from public.profile_reviews where user_id=second_id and status='approved') then
  raise exception 'Both profiles must be approved before creating a connection';
 end if;
 return NEW;
end $function$
"}, "guard_client_profile_fields()": {"acl": "{postgres=X/postgres,service_role=X/postgres}", "definition": "CREATE OR REPLACE FUNCTION public.guard_client_profile_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if current_user in ('anon', 'authenticated') then
    if TG_TABLE_NAME = 'profiles' then
      if TG_OP = 'UPDATE' and (
        new.id is distinct from old.id or
        new.user_type is distinct from old.user_type
      ) then
        raise exception 'Account identity and role can only be changed through an authorized server workflow.'
          using errcode = '42501';
      end if;
    elsif TG_TABLE_NAME = 'investor_profiles' then
      if TG_OP = 'INSERT' and new.is_verified is true then
        raise exception 'Verification is managed by the server.' using errcode = '42501';
      elsif TG_OP = 'UPDATE' then
        if new.is_verified is distinct from old.is_verified then
          raise exception 'Verification is managed by the server.' using errcode = '42501';
        end if;
        if new.user_id is distinct from old.user_id then
          raise exception 'Profile ownership cannot be changed.' using errcode = '42501';
        end if;
      end if;
      -- Nullable legacy alias must never point at another account.
      new.profile_id := new.user_id;
    elsif TG_TABLE_NAME = 'founder_profiles' then
      if TG_OP = 'UPDATE' and new.user_id is distinct from old.user_id then
        raise exception 'Profile ownership cannot be changed.' using errcode = '42501';
      end if;
    end if;
  end if;
  return new;
end $function$
"}, "passport_evidence_tombstone()": {"acl": "{postgres=X/postgres}", "definition": "CREATE OR REPLACE FUNCTION public.passport_evidence_tombstone()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF NEW.passport_private AND OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL THEN
  UPDATE public.profile_verification_checks c SET passport_state='stale'
   WHERE c.passport_claim AND c.passport_state IN
    ('submitted','in_review','supported','needs_changes','rejected') AND EXISTS
     (SELECT 1 FROM public.profile_verification_evidence l WHERE l.check_id=c.id AND l.evidence_id=NEW.id);
 END IF;
 RETURN NEW;
END $function$
"}, "increment_login_tracking(uuid)": {"acl": "{postgres=X/postgres,authenticated=X/postgres}", "definition": "CREATE OR REPLACE FUNCTION public.increment_login_tracking(p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF auth.uid() IS NULL OR p_user_id IS DISTINCT FROM auth.uid() THEN
  RAISE EXCEPTION 'Own authenticated account required' USING ERRCODE='42501';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_user_id AND deleted_at IS NULL) THEN
  RAISE EXCEPTION 'Active profile required' USING ERRCODE='42501';
 END IF;
 INSERT INTO public.user_auth_tracking AS tracking(id,last_login,login_count)
 VALUES(p_user_id,now(),1)
 ON CONFLICT(id) DO UPDATE SET last_login=now(),login_count=coalesce(tracking.login_count,0)+1;
END $function$
"}, "passport_claim_is_current(uuid)": {"acl": "{postgres=X/postgres,service_role=X/postgres}", "definition": "CREATE OR REPLACE FUNCTION public.passport_claim_is_current(p_check uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 SELECT EXISTS (
  SELECT 1 FROM public.profile_verification_checks c
  JOIN public.profile_verifications h ON h.id=c.verification_id
  JOIN public.profiles p ON p.id=c.user_id
  WHERE c.id=p_check AND c.passport_claim AND c.passport_state='supported'
   AND c.expires_at>now() AND h.passport_opted_in_at IS NOT NULL
   AND p.deleted_at IS NULL AND p.user_type=c.role
   AND NOT EXISTS (SELECT 1 FROM public.profile_verification_checks newer
    WHERE newer.user_id=c.user_id AND newer.target_key=c.target_key AND newer.passport_claim
     AND newer.claim_version>c.claim_version)
   AND (c.source_kind<>'manual_evidence' OR EXISTS (
    SELECT 1 FROM public.profile_verification_evidence l JOIN public.trust_evidence e ON e.id=l.evidence_id
    WHERE l.check_id=c.id AND e.passport_private AND e.deleted_at IS NULL AND e.owner_id=c.user_id))
   AND NOT EXISTS (SELECT 1 FROM public.profile_verification_evidence l
    JOIN public.trust_evidence e ON e.id=l.evidence_id
    WHERE l.check_id=c.id AND (e.deleted_at IS NOT NULL OR NOT e.passport_private))
 );
$function$
"}, "sync_investor_profile_aliases()": {"acl": "{postgres=X/postgres,=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres}", "definition": "CREATE OR REPLACE FUNCTION public.sync_investor_profile_aliases()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.profile_id := coalesce(new.profile_id, new.user_id);

  new.firm_name := coalesce(new.firm_name, new.fund_name);
  new.fund_name := coalesce(new.fund_name, new.firm_name);

  new.investment_stage := coalesce(new.investment_stage, new.preferred_stages, '{}'::text[]);
  new.preferred_stages := coalesce(new.preferred_stages, new.investment_stage, '{}'::text[]);

  new.industries_of_interest := coalesce(new.industries_of_interest, new.preferred_industries, '{}'::text[]);
  new.preferred_industries := coalesce(new.preferred_industries, new.industries_of_interest, '{}'::text[]);

  new.ticket_size_min := coalesce(new.ticket_size_min, new.check_range_min);
  new.check_range_min := coalesce(new.check_range_min, new.ticket_size_min);

  new.ticket_size_max := coalesce(new.ticket_size_max, new.check_range_max);
  new.check_range_max := coalesce(new.check_range_max, new.ticket_size_max);

  new.geographic_focus := coalesce(new.geographic_focus, new.geography_focus);
  new.geography_focus := coalesce(new.geography_focus, new.geographic_focus);

  new.portfolio_count := coalesce(new.portfolio_count, new.total_investments, 0);
  new.total_investments := coalesce(new.total_investments, new.portfolio_count, 0);

  new.successful_exits := coalesce(new.successful_exits, new.exits, 0);
  new.exits := coalesce(new.exits, new.successful_exits, 0);

  new.investment_thesis := coalesce(new.investment_thesis, new.what_i_look_for);
  new.what_i_look_for := coalesce(new.what_i_look_for, new.investment_thesis);

  new.updated_at := now();
  return new;
end;
$function$
"}, "capture_matching_request_event()": {"acl": "{postgres=X/postgres,service_role=X/postgres}", "definition": "CREATE OR REPLACE FUNCTION public.capture_matching_request_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare kind text;
begin
 if TG_OP = 'INSERT' and new.status = 'pending' then
  kind := 'request_sent';
 elsif TG_OP = 'UPDATE' and new.status is distinct from old.status and new.status in ('accepted','declined') then
  kind := case when new.status = 'accepted' then 'request_accepted' else 'request_declined' end;
 else
  return new;
 end if;
 insert into public.matching_events(actor_id,target_id,event_type,reference,payload)
 values (
 case when kind='request_sent' then new.sender_id else new.receiver_id end,
 case when kind='request_sent' then new.receiver_id else new.sender_id end,
 kind,new.id::text,jsonb_build_object('source','connection_requests')
 ) on conflict(actor_id,target_id,event_type,reference) do nothing;
 return new;
end;
$function$
"}, "enforce_active_registration_role()": {"acl": "{postgres=X/postgres,=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres}", "definition": "CREATE OR REPLACE FUNCTION public.enforce_active_registration_role()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if TG_OP = 'INSERT' then
