end
$function$
"}, "record_evidence_review(uuid,uuid,text,text)": {"acl": "{postgres=X/postgres,service_role=X/postgres}", "definition": "CREATE OR REPLACE FUNCTION public.record_evidence_review(p_evidence uuid, p_reviewer uuid, p_status text, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if p_status not in ('supported','needs_changes','rejected') or length(trim(p_note))<20 or length(p_note)>1000 then
  raise exception 'Invalid review';
 end if;
 update public.trust_evidence set review_status=p_status,review_note=p_note,reviewed_by=p_reviewer,reviewed_at=now()
 where id=p_evidence and owner_id<>p_reviewer;
 if not found then raise exception 'Evidence unavailable or self-review prohibited'; end if;
 insert into public.evidence_reviews(evidence_id,reviewer_id,status,note) values(p_evidence,p_reviewer,p_status,p_note);
end; $function$
"}, "decide_profile_review(uuid,integer,uuid,text,text)": {"acl": "{postgres=X/postgres,service_role=X/postgres}", "definition": "CREATE OR REPLACE FUNCTION public.decide_profile_review(p_user uuid, p_revision integer, p_admin uuid, p_status text, p_note text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if p_user=p_admin then raise exception 'Self approval is prohibited'; end if;
 if p_status not in ('approved','changes_requested','rejected') or length(trim(p_note))<20 or length(p_note)>1500 then raise exception 'Invalid decision'; end if;
 update public.profile_reviews set status=p_status,decision_note=p_note,reviewed_by=p_admin,reviewed_at=now(),updated_at=now()
 where user_id=p_user and revision=p_revision and status='pending';
 if not found then return false; end if;
 insert into public.profile_review_history(user_id,revision,status,note,reviewer_id) values(p_user,p_revision,p_status,p_note,p_admin);
 return true;
end $function$
"}, "create_conversation_with_participants(uuid,uuid,text)": {"acl": "{postgres=X/postgres,service_role=X/postgres}", "definition": "CREATE OR REPLACE FUNCTION public.create_conversation_with_participants(p_created_by uuid, p_other_user uuid, p_type text DEFAULT 'direct'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE conversation uuid;
BEGIN
 IF current_user NOT IN ('service_role','postgres') THEN
  RAISE EXCEPTION 'Backend authority required' USING ERRCODE='42501';
 END IF;
 IF p_created_by IS NULL OR p_other_user IS NULL OR p_created_by=p_other_user
  OR coalesce(p_type,'direct')<>'direct' THEN
  RAISE EXCEPTION 'Two distinct participants and direct conversation required' USING ERRCODE='22023';
 END IF;
 IF (SELECT count(*) FROM public.profiles WHERE id IN (p_created_by,p_other_user)
     AND deleted_at IS NULL)<>2 THEN
  RAISE EXCEPTION 'Active participants required' USING ERRCODE='42501';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.connections
  WHERE (user_1=p_created_by AND user_2=p_other_user) OR (user_2=p_created_by AND user_1=p_other_user)) THEN
  RAISE EXCEPTION 'Connect first before opening a conversation' USING ERRCODE='42501';
 END IF;
 -- Serialize a pair to prevent duplicate rooms from simultaneous backend calls.
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
  least(p_created_by,p_other_user)::text||':'||greatest(p_created_by,p_other_user)::text,0));
 SELECT a.conversation_id INTO conversation FROM public.conversation_participants a
 JOIN public.conversation_participants b ON b.conversation_id=a.conversation_id
 JOIN public.conversations c ON c.id=a.conversation_id
 WHERE a.user_id=p_created_by AND b.user_id=p_other_user AND c.type='direct'
  AND (SELECT count(*) FROM public.conversation_participants x WHERE x.conversation_id=c.id)=2
 ORDER BY c.created_at,c.id LIMIT 1;
 IF conversation IS NULL THEN
  INSERT INTO public.conversations(type,created_at,updated_at,last_message_at)
  VALUES('direct',now(),now(),now()) RETURNING id INTO conversation;
  INSERT INTO public.conversation_participants(conversation_id,user_id,created_at)
  VALUES(conversation,p_created_by,now()),(conversation,p_other_user,now());
  INSERT INTO public.conversation_members(conversation_id,user_id,joined_at)
  VALUES(conversation,p_created_by,now()),(conversation,p_other_user,now());
 END IF;
 RETURN conversation;
END $function$
"}}

